#!/usr/bin/env node
import fs from "fs";
import { convert } from "../index.js";

const inputFile = process.argv[2];
const outputFile = process.argv[3] || "postman-collection.json";

if (!inputFile) {
  console.error("📖 Usage: hoppscotch-to-postman <input.json> [output.json]");
  process.exit(1);
}

try {
  const hoppscotchData = JSON.parse(fs.readFileSync(inputFile, "utf8"));
  const postmanData = convert(hoppscotchData);

  fs.writeFileSync(outputFile, JSON.stringify(postmanData, null, 2));
  console.log(`✅ Converted! Saved to ${outputFile}`);
} catch (err) {
  console.error("❌ Error:", err.message);
  process.exit(1);
}
